mapper.select:
/* UserMapper.selectUserInfo 사용자 정보 조회 */ SELECT USER_SEQ, USER_ID, USER_PWD, USER_NAME, ISNULL(TEL_NO, '') AS TEL_NO , ISNULL(HP_NO, '') AS HP_NO, ISNULL(EMAIL, '') AS EMAIL, COMPANY_CODE , USER_GRADE, SMS_YN, EXCEL_YN, FILE_YN, DB_YN, REG_DATE, CHG_DATE , USE_YN, DEL_FLAG, ISNULL(USER_TEXT0, '') AS USER_TEXT0, ISNULL(USER_TEXT1, '') AS USER_TEXT1, LMS_YN, MMS_YN, ISNULL(ENC_1_PA, '') AS ENC_1_PA FROM T_SMS_CLIENT WHERE USER_ID = #{userId}
AND DEL_FLAG = #{delFlag}
ORDER BY USER_SEQ DESC

  	/*
  		UserMapper.selectUserInfoListCount 사용자 정보 목록 갯수
  	*/
    SELECT 
		COUNT(*)
	FROM T_SMS_CLIENT
	WHERE 1 = 1

		AND USER_ID = #{userId}


		AND USER_GRADE = #{userGrade}


		AND COMPANY_CODE = #{companyCode}

	AND DEL_FLAG = 'N'

/* UserMapper.selectUserInfoList 사용자 정보 목록 조회 */ SELECT USER_SEQ, USER_ID, USER_NAME, TEL_NO, HP_NO, EMAIL, COMPANY_CODE , USER_GRADE, SMS_YN, EXCEL_YN, FILE_YN, DB_YN, REG_DATE, CHG_DATE , USE_YN, DEL_FLAG, USER_TEXT0, USER_TEXT1, LMS_YN, MMS_YN FROM ( SELECT USER_SEQ, USER_ID, USER_NAME, ISNULL(TEL_NO, '') AS TEL_NO , ISNULL(HP_NO, '') AS HP_NO, ISNULL(EMAIL, '') AS EMAIL, COMPANY_CODE , USER_GRADE, SMS_YN, EXCEL_YN, FILE_YN, DB_YN, REG_DATE, CHG_DATE , USE_YN, DEL_FLAG, ISNULL(USER_TEXT0, '') AS USER_TEXT0, ISNULL(USER_TEXT1, '') AS USER_TEXT1, LMS_YN, MMS_YN FROM T_SMS_CLIENT WHERE 1 = 1
AND USER_ID = #{userId}
AND USER_GRADE = #{userGrade}
AND COMPANY_CODE = #{companyCode}
AND DEL_FLAG = 'N' ) T
ORDER BY
${s.selector}
DESC ASC
ORDER BY USER_SEQ DESC
OFFSET #{skip} ROWS FETCH NEXT #{take} ROWS ONLY

mapper.insert:
	/*
  		UserMapper.insertUserInfo 사용자 정보 등록
  	*/
  	INSERT INTO T_SMS_CLIENT (
		USER_ID, USER_PWD, USER_NAME, USER_GRADE, COMPANY_CODE
		, HP_NO, EXCEL_YN, FILE_YN, DB_YN, LMS_YN, MMS_YN, USE_YN, ENC_1_PA
	) VALUES (
		#{userId}, #{userPwd}, #{userName}, #{userGrade}, #{companyCode}
		, #{hpNo}, #{excelYn}, #{fileYn}, #{dbYn}, #{lmsYn}, #{mmsYn}, #{useYn}, #{enc1Pa}
	)

mapper.update:
/* UserMapper.updateUserInfo 사용자 정보 수정 */ UPDATE T_SMS_CLIENT
USER_NAME = #{userName}, USER_GRADE = #{userGrade}, COMPANY_CODE = #{companyCode},
HP_NO = #{hpNo}, SMS_YN = #{smsYn}, EXCEL_YN = #{excelYn}, FILE_YN = #{fileYn}, DB_YN = #{dbYn}, LMS_YN = #{lmsYn}, MMS_YN = #{mmsYn}, USE_YN = #{useYn}, ENC_1_PA = #{enc1Pa}, CHG_DATE = CONVERT(VARCHAR(10), GETDATE(), 112) + REPLACE(CONVERT(VARCHAR(8), GETDATE(), 108), ':', '')
WHERE USER_ID = #{userId}

	/*
  		UserMapper.deleteUserInfo 사용자 정보 삭제
  	*/
	UPDATE T_SMS_CLIENT SET
		DEL_FLAG = 'Y'
	WHERE USER_ID = #{userId}

	/*
  		UserMapper.updateUserPassword 사용자 비밀번호 변경
  	*/
	UPDATE T_SMS_CLIENT

	        USER_PWD = #{userPwd},
			ENC_1_PA = #{enc1Pa}

	WHERE USER_ID = #{userId}
